    # Remove spaces and punctuation from the input string
    cleaned_string = ''.join(char for char in string if char.isalpha())

    # Convert all characters to lowercase
    cleaned_string = cleaned_string.lower()

    # Create a set to store distinct characters
    distinct_chars = set()

    # Iterate through the string and add each distinct character to the set
    for char in cleaned_string:
        distinct_chars.add(char)

    # Return the size of the set as the result
    return len(distinct_chars)
